(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.012-t*0.22)*12;
  const w1y = Math.cos(y*0.016-t*0.28)*16+Math.sin(x*0.014+t*0.33)*11;
  const w2x = Math.sin((x+w1y)*0.025-t*0.15)*8+Math.cos((y+w1x)*0.02+t*0.18)*6;
  const w2y = Math.cos((y+w1x)*0.022+t*0.17)*9+Math.sin((x+w1y)*0.019-t*0.2)*7;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.95],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.05],
    [80+Math.sin(t*0.45+3)*110, 140+Math.cos(t*0.65+2)*70, 0.11, 2.1, 0.88],
    [400+Math.cos(t*0.55+1)*70, 100+Math.sin(t*0.75+4)*80, 0.065, 1.8, 1.15]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave1=Math.sin(d*f-t*sp), wave2=Math.sin(d*f*1.618-t*sp*0.78+0.5);
    aS+=wave1*w; iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    aS2+=wave2*w; iS2+=Math.sin(d*f*0.5-t*sp*0.4+2.8)*w;
  }
  const n=8;
  const act=(aS+aS2*0.4)/n, inh=(iS+iS2*0.3)/n;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const vortex=Math.sin(dist*0.03-ang*5+t*0.8)*Math.exp(-dist*0.005)*0.3;
  const micro=(Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)+Math.sin((sx-sy)*0.2+t*4)*0.5)*0.15;
  const lap = (act - inh*0.65 + bg*0.25 + spiral + vortex + micro)*2.2;
  const reaction = Math.tanh(lap);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const ridges=Math.abs(reaction)>0.55?Math.sin(reaction*12)*0.15:0;
  const glow=Math.exp(-Math.abs(reaction)*2)*0.2*(Math.sin(t*1.5)*0.5+0.5);
  const blend=reaction*0.6+cell*0.2+ridges+glow, v=blend*0.5+0.5;
  const hShift=Math.sin(t*0.2)*0.08;
  const pal=[
    [12,22,82],[18,55,125],[20,95,130],[25,140,115],
    [120,175,80],[210,190,60],[225,140,65],[200,80,70],
    [160,50,80],[100,30,70],[50,20,65],[12,22,82]
  ];
  const adj=Math.max(0,Math.min(pal.length-1.001,v*(pal.length-1)+hShift*pal.length));
  const i=Math.min(adj|0,pal.length-2), f=adj-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const hi=Math.max(0,reaction-0.3)*0.4;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+hi*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+hi*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+hi*15)|0)
  ];
}
